interface BriefSuggestionFieldProps {
  field: 'title' | 'artist_name' | 'genre' | 'mood' | 'era' | 'theme';
  label: string;
  hint: string;
  placeholder: string;
  suggestions?: string[];
  value: string;
  onChange: (value: string) => void;
}

const BriefSuggestionField: React.FC<BriefSuggestionFieldProps> = ({ field, label, hint, placeholder, suggestions, value, onChange }) => {
  const [open, setOpen] = useState(false);
  const [filtering, setFiltering] = useState(false);
  const inputId = `studio-${field}`;
  const listId = `${inputId}-suggestions`;
  const query = value.trim().toLowerCase();
  const filteredSuggestions = suggestions?.filter(suggestion => !query || suggestion.toLowerCase().includes(query)) || [];
  const visibleSuggestions = filtering && filteredSuggestions.length > 0 ? filteredSuggestions : suggestions || [];

  return <div className="relative text-xs font-bold text-slate-600" onBlur={event => { if (!event.currentTarget.contains(event.relatedTarget as Node | null)) setOpen(false); }}>
    <label htmlFor={inputId}>{label}<span className="block mt-0.5 text-[10px] font-medium text-slate-400 normal-case">{hint}</span></label>
    <div className="relative mt-1.5">
      <input
        id={inputId}
        role={suggestions ? 'combobox' : undefined}
        aria-autocomplete={suggestions ? 'list' : undefined}
        aria-expanded={suggestions ? open : undefined}
        aria-controls={suggestions ? listId : undefined}
        placeholder={placeholder}
        value={value}
        onChange={event => { onChange(event.target.value); if (suggestions) { setFiltering(true); setOpen(true); } }}
        onKeyDown={event => {
          if (suggestions && event.key === 'ArrowDown') { event.preventDefault(); setFiltering(false); setOpen(true); }
          if (event.key === 'Escape') setOpen(false);
        }}
        className={`w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2.5 text-sm placeholder:text-slate-300 ${suggestions ? 'pr-11' : ''}`}
      />
      {suggestions && <button type="button" aria-label={`Show ${label.toLowerCase()} suggestions`} aria-expanded={open} aria-controls={listId} onClick={() => { setFiltering(false); setOpen(current => !current); }} className="absolute inset-y-0 right-0 flex w-11 items-center justify-center rounded-r-xl text-slate-400 hover:bg-slate-100 hover:text-emerald-700 focus:outline-none focus:ring-2 focus:ring-inset focus:ring-emerald-500"><ChevronDown size={17} className={`transition-transform ${open ? 'rotate-180' : ''}`} /></button>}
    </div>
    {suggestions && open && <div id={listId} role="listbox" className="absolute z-30 mt-1 max-h-56 w-full overflow-auto rounded-xl border border-slate-200 bg-white p-1.5 shadow-xl">
      {visibleSuggestions.map(suggestion => <button type="button" role="option" aria-selected={suggestion === value} key={suggestion} onClick={() => { onChange(suggestion); setFiltering(false); setOpen(false); }} className={`block w-full rounded-lg px-3 py-2.5 text-left text-sm font-medium normal-case ${suggestion === value ? 'bg-emerald-50 text-emerald-800' : 'text-slate-700 hover:bg-slate-50'}`}>{suggestion}</button>)}
      <p className="px-3 py-2 text-[10px] font-medium normal-case text-slate-400">You can also type your own.</p>
    </div>}
  </div>;
};

interface StudioConfirmation {
  title: string;
  message: string;
  confirmLabel: string;
  tone?: 'primary' | 'danger';
  action: () => Promise<void>;
}

